/* Superadmin Control Center */
(function(){
const {ic,chip,card,head,tbl,av,empty,tabs,panel,wtabs,field,inp,sel,sw,prog,D,reg,S,toast,modal,close,U,$,$$,A,M}=Object.assign({},OS);
const W=k=>OS.WS[k];
const list=a=>`<div class="col">${a.join('')}</div>`;
const row=(a,t,s,r)=>`<div class="slot">${a}<div class="sp"><b class="sm">${t}</b><div class="xs mut">${s}</div></div>${r||''}</div>`;
reg('superadmin','Overview',()=>head(['Platform overview','Everything running across all clinics.'],`<a class="btn pri" href="${U('superadmin/clinics')}">${ic('building')}All clinics</a>`)+
 `<div class="grid g4 keep2" style="margin-bottom:18px">${OS.kpi('Clinics','5','building','superadmin/clinics')}${OS.kpi('Platform users','19','users','superadmin/users','t2')}${OS.kpi('On trial','1','clock','superadmin/subscriptions','t3')}${OS.kpi('WhatsApp connected','3','phone','superadmin/whatsapp','t4')}</div>`+
 `<div class="grid g21" style="margin-bottom:18px">${card('Recent clinics',tbl(['Clinic','Owner','City','Plan','Status'],D.clinics.map(c=>({go:'superadmin/clinics/c-201',c:[`<div class="row">${av(c[1],null,'sm')}<b>${c[1]}</b></div>`,c[2],c[3],c[4],OS.chip(c[5])]}))))}${card('API health',`<div class="band" style="margin-bottom:12px"><span class="bi">${ic('server')}</span><div class="sp"><b>API is reachable</b><div class="xs mut">Process status only</div></div>${chip('UP')}</div><a class="btn soft" style="width:100%" href="${U('superadmin/health')}">Open health</a>`)}</div>`+
 card('Needs attention',list([row(ic('alert'),'City Specialists','Subscription payment is past due',`<a class="btn gh sm" href="${U('superadmin/clinics/c-201')}">Review</a>`),row(ic('phone'),'Smile Craft Dental','On trial, WhatsApp not yet connected',`<a class="btn gh sm" href="${U('superadmin/whatsapp')}">Open</a>`)])));
reg('superadmin/clinics','Clinics',()=>wtabs(W('sa_c'),'superadmin/clinics')+head(['Clinics','Every clinic workspace on the platform.'])+
 `<div class="row wrap rv" style="margin-bottom:16px"><div class="iw" style="flex:1;min-width:240px">${ic('search')}<input class="inp" placeholder="Search clinics" data-act="clq"></div>${OS.sel(['All statuses','Active','Trial','Past due','Suspended'])}${OS.sel(['All plans','Starter','Pro','Enterprise'])}</div><div id="cltb">`+tbl(['Clinic','Owner','City','Plan','Status','WhatsApp','AI'],D.clinics.map(c=>({go:'superadmin/clinics/c-201',c:[`<div class="row">${av(c[1],null,'sm')}<b>${c[1]}</b></div>`,c[2],c[3],c[4],OS.chip(c[5]),c[6]?OS.chip('CONNECTED'):OS.chip('DISCONNECTED'),c[7]?OS.chip('PUBLISHED'):OS.chip('DRAFT')]})))+'</div>');
document.addEventListener('input',e=>{if(e.target.dataset.act==='clq'){const q=e.target.value.toLowerCase();$$('#cltb tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)?'':'none')}});
reg('superadmin/clinics/c-201','Clinics',()=>`<a class="btn gh sm" href="${U('superadmin/clinics')}" style="margin-bottom:14px">${ic('chevL')}All clinics</a>`+head(['Noor Family Clinic','Clinic profile, subscription and activity.'],`<button class="btn gh" data-open="patch">${ic('edit')}Change status or plan</button>`)+
 `<div class="grid g4 keep2" style="margin-bottom:18px">${OS.kpi('Patients','312','users','')}${OS.kpi('Appointments','142','calendar','','t2')}${OS.kpi('Messages','268','chat','','t3')}${OS.kpi('Staff','4','userplus','','t4')}</div>`+
 tabs('cd',[['Profile','building'],['Subscription','card'],['WhatsApp','phone'],['AI','sparkles'],['Activity','clock']])+
 panel('cd',0,card('Profile',`<dl class="kv"><dt>Owner</dt><dd>Dr. Hina Malik</dd><dt>Specialty</dt><dd>General practice</dd><dt>City</dt><dd>Multan</dd><dt>Email</dt><dd>hello@noorclinic.example</dd><dt>Registered</dt><dd>04 Oct 2026</dd></dl>`))+
 panel('cd',1,card('Subscription',`<dl class="kv"><dt>Plan</dt><dd>Pro · $59 per month</dd><dt>Status</dt><dd>${OS.chip('ACTIVE')}</dd><dt>Next invoice</dt><dd>01 Nov 2026</dd></dl>`))+
 panel('cd',2,card('WhatsApp',`<dl class="kv"><dt>Status</dt><dd>${OS.chip('CONNECTED')}</dd><dt>Number</dt><dd>+92 61 111 0123</dd></dl><button class="btn dng sm" style="margin-top:14px" data-open="revoke">Revoke connection</button>`))+
 panel('cd',3,card('AI receptionist',`<dl class="kv"><dt>Status</dt><dd>${OS.chip('PUBLISHED')}</dd><dt>Last published</dt><dd>12 Oct 2026</dd></dl>`))+
 panel('cd',4,card('Activity',`<div class="tl"><div><b class="sm">Owner signed in</b><div class="xs mut">Today 09:02</div></div><div><b class="sm">AI changes published</b><div class="xs mut">12 Oct</div></div><div><b class="sm">WhatsApp connected</b><div class="xs mut">12 Oct</div></div></div>`)));
M.patch=()=>modal('Change status or plan',`${field('Status',sel(['Active','Trial','Past due','Suspended']))}${field('Plan',sel(['Starter','Pro','Enterprise'],'Pro'))}<p class="xs mut">Changes apply to this clinic only and are recorded in the audit log.</p>`,`<button class="btn gh" data-close>Cancel</button><button class="btn pri" data-toast="Clinic updated" data-close>Save</button>`);
M.revoke=()=>modal('Revoke WhatsApp connection?','<p>The clinic will stop receiving WhatsApp messages until they reconnect.</p>',`<button class="btn gh" data-close>Cancel</button><button class="btn dng" data-toast="Connection revoked" data-close>Revoke</button>`);
reg('superadmin/users','Users',()=>wtabs(W('sa_c'),'superadmin/users')+head(['Users','People with accounts on the platform.'])+tbl(['Name','Email','Role','Clinic','Status'],[['Dr. Hina Malik','hina@noorclinic.example','Owner','Noor Family Clinic',OS.chip('ACTIVE')],['Sadia Karim','sadia@noorclinic.example','Receptionist','Noor Family Clinic',OS.chip('ACTIVE')],['Dr. Adeel Raza','adeel@smilecraft.example','Owner','Smile Craft Dental',OS.chip('ACTIVE')],['Talha Javed','talha@noorclinic.example','Assistant','Noor Family Clinic',OS.chip('INVITED')]].map(r=>r)));
const PL=[['Starter','$29'],['Pro','$59'],['Enterprise','$99']];
reg('superadmin/subscriptions','Billing',()=>wtabs(W('sa_b'),'superadmin/subscriptions')+head(['Billing','Plans and each clinic’s subscription.'])+`<div class="grid g3" style="margin-bottom:18px">${PL.map(p=>`<div class="card hv rv"><b class="sm mut">${p[0]}</b><div style="font:800 34px var(--fh);margin:6px 0">${p[1]}<small class="mut" style="font-size:14px">/mo</small></div><span class="chip">${D.clinics.filter(c=>c[4]===p[0]).length} clinics</span></div>`).join('')}</div>`+tbl(['Clinic','Plan','Status','Next invoice'],D.clinics.map(c=>[c[1],c[4],OS.chip(c[5]),'01 Nov 2026'])));
reg('superadmin/stripe','Billing',()=>wtabs(W('sa_b'),'superadmin/stripe')+head(['Plans','The three Stripe plans.'])+`<div class="grid g3">${PL.map(p=>card(p[0],`<div style="font:800 30px var(--fh)">${p[1]}<small class="mut" style="font-size:14px">/mo</small></div><div class="xs mut" style="margin:6px 0 14px">Stripe price linked</div><button class="btn gh sm" data-toast="Opening Stripe">View in Stripe</button>`)).join('')}</div>`);
reg('superadmin/revenue','Billing',()=>wtabs(W('sa_b'),'superadmin/revenue')+head(['Billing analytics','Subscription numbers across the platform.'])+`<div class="grid g21">${card('Monthly recurring',OS.line([210,240,240,290,330,330,389]),'','','Sample data, last 7 months')}${card('Plan mix',OS.donut([['Starter',2],['Pro',2],['Enterprise',1]]))}</div>`);
reg('superadmin/whatsapp','WhatsApp',()=>wtabs(W('sa_w'),'superadmin/whatsapp')+head(['WhatsApp','Clinic connections.'])+tbl(['Clinic','Number','Status','Last webhook',''],D.clinics.map(c=>[c[1],c[6]?'+92 61 111 0123':'—',c[6]?OS.chip('CONNECTED'):OS.chip('DISCONNECTED'),c[6]?'2 min ago':'—',c[6]?`<button class="btn dng sm" data-open="revoke">Revoke</button>`:''])));
reg('superadmin/announcements','WhatsApp',()=>wtabs(W('sa_w'),'superadmin/announcements')+head(['Announcements','Send a notice to all clinic owners now.'])+`<div class="grid g21">${card('New announcement',`${field('Title',inp('Scheduled maintenance'))}${field('Message',`<textarea class="txt"></textarea>`)}<button class="btn pri" data-toast="Announcement sent">${ic('send')}Send now</button>`)}${card('About',`<p class="sm mut">Announcements are sent immediately. Past announcements are not archived here.</p>`)}</div>`);
reg('superadmin/support','WhatsApp',()=>wtabs(W('sa_w'),'superadmin/support')+head(['Support','Questions from clinics.'])+tbl(['Clinic','Subject','Received','Status'],[['Smile Craft Dental','Cannot connect WhatsApp','Today',OS.chip('OPEN')],['City Specialists','Invoice question','Yesterday',OS.chip('RESOLVED')]]));
reg('superadmin/settings','Settings',()=>wtabs(W('sa_s'),'superadmin/settings')+head(['Platform settings','Defaults for every clinic.'])+card('General',`<div class="grid g2" style="gap:0 16px">${field('Platform name',inp('','Clinicos'))}${field('Support email',inp('','support@doctorsmyagency.example'))}${field('Trial length',sel(['14 days'],'14 days'))}${field('Default language',sel(['English','Urdu']))}</div><button class="btn pri" data-toast="Settings saved">Save</button>`));
reg('superadmin/security','Settings',()=>wtabs(W('sa_s'),'superadmin/security')+head(['Security','Access rules for administrators.'])+card('',[['Require strong passwords',true],['Sign out idle sessions',true]].map(x=>`<div class="row" style="justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--line)"><b class="sm">${x[0]}</b>${sw(x[1])}</div>`).join('')));
reg('superadmin/health','Settings',()=>wtabs(W('sa_s'),'superadmin/health')+head(['Health','Whether the platform process is up.'],`<button class="btn gh" data-toast="Checked just now">${ic('refresh')}Check now</button>`)+`<div class="grid g3">${[['API','UP'],['Database','UP'],['WhatsApp webhook','UP']].map(s=>`<div class="card rv"><div class="row"><span class="fico">${ic('server')}</span><div class="sp"><b>${s[0]}</b></div>${OS.chip(s[1])}</div></div>`).join('')}</div>`);
reg('superadmin/audit','Settings',()=>wtabs(W('sa_s'),'superadmin/audit')+head(['Audit','Administrator actions.'])+tbl(['When','Who','Action'],[['Today 10:44','Superadmin','Changed plan for Noor Family Clinic'],['Today 09:10','Superadmin','Sent announcement'],['Yesterday','Superadmin','Revoked WhatsApp for City Specialists']]));
reg('superadmin/integrations','Settings',()=>wtabs(W('sa_s'),'superadmin/integrations')+head(['Integrations','Services connected to the platform.'])+`<div class="grid g3">${[['Stripe','card'],['Meta WhatsApp','phone'],['Email delivery','mail']].map(i=>`<div class="card hv rv"><span class="fico">${ic(i[1])}</span><h3 style="margin:12px 0 8px">${i[0]}</h3>${OS.chip('CONNECTED')}</div>`).join('')}</div>`);
reg('superadmin/api','Settings',()=>wtabs(W('sa_s'),'superadmin/api')+head(['API','Keys for platform integrations.'],`<button class="btn pri" data-toast="Key created">${ic('plus')}Create key</button>`)+tbl(['Name','Key','Created',''],[['Reporting','sk_••••••••3f2a','01 Oct',`<button class="btn dng sm" data-toast="Key revoked">Revoke</button>`]]));
})();
